	/**
	 * Get raw SVG string.
	 *
	 * @param string $name Icon key.
	 * @return string
	 */
	public static function getRaw( $name ) {
		return isset( self::$icons[ $name ] ) ? self::$icons[ $name ] : '';
	}

	/**
	 * Add or override an icon at runtime.
	 *
	 * @param string $name Icon key.
	 * @param string $svg  Raw svg markup.
	 * @return void
	 */
	public static function set( $name, $svg ) {
		self::$icons[ $name ] = $svg;
	}
